begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select plan(6);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)values('a2220000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','compliance-pages@example.invalid','',now(),'{}','{}',now(),now());
insert into public.platform_user_roles(user_id,role_code)values('a2220000-0000-4000-8000-000000000001','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)select('b2220000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'TEST Compliance '||i,'TEST Compliance '||i,'PENDING','a2220000-0000-4000-8000-000000000001'from generate_series(1,55)i;
insert into public.client_compliance_cases(id,organization_id,status,created_by,updated_at)select('f2220000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,('b2220000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,case when i%2=0 then'DOCUMENTS_REQUIRED'else'PROFILE_IN_PROGRESS'end,'a2220000-0000-4000-8000-000000000001',now()-make_interval(secs=>i)from generate_series(1,55)i;
create temporary table results(k text primary key,v jsonb);grant all on results to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','a2220000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2220000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into results values('page1',public.get_admin_client_compliance_page_v1(1,'all',null)),('page2',public.get_admin_client_compliance_page_v1(2,'all',null)),('direct',public.get_admin_client_compliance_page_v1(1,'all','f2220000-0000-4000-8000-000000000055')),('check',public.get_admin_client_compliance_page_v1(1,'check',null));
select throws_ok($$select public.get_admin_client_compliance_page_v1(0,'all',null)$$,'22023','INVALID_COMPLIANCE_PAGE','invalid page rejected');
reset role;
select is((select jsonb_array_length(v->'cases')from results where k='page1'),50,'queue page has explicit fifty-row size');
select is((select(v->>'has_next')::boolean from results where k='page1'),true,'later cases remain reachable through next page');
select ok((select exists(select 1 from jsonb_array_elements(v->'cases')c where c->>'id'='f2220000-0000-4000-8000-000000000055')from results where k='page2'),'last case appears on a later page');
select is((select v#>>'{cases,0,id}'from results where k='direct'),'f2220000-0000-4000-8000-000000000055','detail lookup is by exact ID beyond first fifty');
select ok((select not exists(select 1 from jsonb_array_elements(v->'cases')c where c->>'status'not in('DOCUMENTS_REQUIRED','UNDER_REVIEW'))and(v#>>'{counts,all}')::int>=55 from results where k='check'),'stable server filter and global totals include later pages');
select*from finish();rollback;
